/** Explicit opt-in isolated native diagnostic. Never enables earned acceptance. */
@Mod(modid="narutoarenas_privateqa",name="Private arena native diagnostics",version="0.1.0",serverSideOnly=true,acceptableRemoteVersions="*",dependencies="required-after:narutoarenas")
public final class NativeProbe {
 static MinecraftServer server;static List<ArenaDirector.Definition> defs;static boolean enabled;static int wait,index;static JsonObject report;static Path cwd;static JsonArray results;static EntityPlayerMP player;static long started;static Entity active;static JsonObject activeBoss;static LivingDeathEvent deathEvent;static EntityJoinWorldEvent joinEvent;static boolean controllerStarted,combatStarted;static Class<?> controllerClass,combatClass;static int activeStartTicks,activeServerTicks,routeIndex;static ArenaDirector.Definition activeDef;static JsonObject activeRow;
 @Mod.EventHandler public void started(FMLServerStartedEvent e){begin(net.minecraftforge.fml.common.FMLCommonHandler.instance().getMinecraftServerInstance(),ArenaDirector.DEFINITIONS);net.minecraftforge.common.MinecraftForge.EVENT_BUS.register(this);}
 @SubscribeEvent public void serverTick(TickEvent.ServerTickEvent e){if(e.phase==TickEvent.Phase.END)tick();}
 static long networkTicks;static final Map<String,Integer> playerTicks=new LinkedHashMap<>();
 @SubscribeEvent(priority=EventPriority.NORMAL) public void privateNetworkTick(TickEvent.ServerTickEvent e){if(e.phase!=TickEvent.Phase.START||!enabled||server==null)return;for(EntityPlayerMP current:new ArrayList<>(server.getPlayerList().getPlayers()))if(current.connection instanceof Quiet&&current.connection.netManager.isChannelOpen()){current.connection.netManager.processReceivedPackets();networkTicks++;}}
 @SubscribeEvent public void nativePlayerTick(TickEvent.PlayerTickEvent e){if(e.phase!=TickEvent.Phase.END||!enabled||!(e.player instanceof EntityPlayerMP)||!(((EntityPlayerMP)e.player).connection instanceof Quiet))return;String key=e.player.getUniqueID().toString();playerTicks.put(key,playerTicks.containsKey(key)?playerTicks.get(key)+1:1);}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void join(EntityJoinWorldEvent e){if(e.getEntity()==active)joinEvent=e;}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void death(LivingDeathEvent e){if(e.getEntityLiving()==active)deathEvent=e;}
 static void begin(MinecraftServer s,List<ArenaDirector.Definition> d){
  enabled=Boolean.getBoolean("hbv.arenas.nativeProbe");if(!enabled)return;cwd=Paths.get("").toAbsolutePath().normalize();
  try{if(!Files.isRegularFile(cwd.resolve(".hbv-arenas-native-probe"))||!new String(Files.readAllBytes(cwd.resolve(".hbv-arenas-native-probe")),StandardCharsets.US_ASCII).trim().equals("NEW_FRESH_ARENA_WORLD_ONLY")||!s.getFolderName().equals("arena-preview")||s.getPlayerList().getCurrentPlayerCount()!=0)throw new IllegalStateException("Native arena guard rejected runtime");}catch(IOException e){throw new RuntimeException(e);}
  server=s;s.getWorld(0).getGameRules().setOrCreateGameRule("doMobSpawning","false");defs=new ArrayList<>(d);wait=80;index=0;report=new JsonObject();results=new JsonArray();report.add("arenas",results);report.addProperty("scope","ISOLATED_NATIVE_REGISTRY_GEOMETRY_AND_CONTROLLER_DIAGNOSTIC");report.addProperty("full_encounter_acceptance",false);report.addProperty("graphical_acceptance",false);report.addProperty("earned_rewards_enabled",false);report.addProperty("iteration",System.getProperty("hbv.arenas.probeIteration","1"));started=System.nanoTime();
 }
 static void tick(){if(!enabled)return;
  if(active!=null){activeServerTicks++;WorldServer world=server.getWorld(0);prewarm(world,active.getPosition());if(activeServerTicks==40&&active instanceof EntityLivingBase&&!active.isDead&&((EntityLivingBase)active).getHealth()>0){activeBoss.addProperty("registered_player_contact_damage_accepted",active.attackEntityFrom(net.minecraft.util.DamageSource.causePlayerDamage(player),100000F));activeBoss.addProperty("after_player_contact_health",((EntityLivingBase)active).getHealth());}}
  if(active!=null&&!Boolean.getBoolean("hbv.arenas.registryOnly"))routeBatch();if(--wait>0)return;if(activeDef!=null&&activeDef.samples!=null&&routeIndex<activeDef.samples.length&&!Boolean.getBoolean("hbv.arenas.registryOnly")){wait=1;return;}
  if(active!=null){WorldServer world=server.getWorld(0);activeBoss.addProperty("after_lethal_observation_server_ticks",activeServerTicks);activeBoss.addProperty("actual_body_ticks_advanced",active.ticksExisted-activeStartTicks);activeBoss.addProperty("native_area_loaded32",world.isAreaLoaded(active.getPosition().add(-32,0,-32),active.getPosition().add(32,0,32)));activeBoss.addProperty("native_loaded_entity_list_contains_exact_body",world.loadedEntityList.contains(active));activeBoss.addProperty("native_uuid_lookup_exact_body",world.getEntityFromUuid(active.getUniqueID())==active);activeBoss.addProperty("official_body_world_player_list_contains",world.playerEntities.contains(player));activeBoss.addProperty("death_event_emitted",deathEvent!=null);activeBoss.addProperty("death_event_final_cancelled",deathEvent!=null&&deathEvent.isCanceled());activeBoss.addProperty("after_observation_dead",active.isDead);activeBoss.addProperty("after_observation_present",world.getEntityFromUuid(active.getUniqueID())!=null);if(active instanceof EntityLivingBase)activeBoss.addProperty("after_observation_health",((EntityLivingBase)active).getHealth());active.setDead();active=null;activeBoss=null;deathEvent=null;joinEvent=null;}
  if(Boolean.getBoolean("hbv.arenas.controllerOnly")){try{ensurePlayer(server.getWorld(0));index=defs.size();report.addProperty("scope","FOCUSED_CONTROLLER_ONLY_NO_GEOMETRY_ACCEPTANCE");}catch(Exception failure){throw new RuntimeException(failure);}}
  if(index<defs.size()){ArenaDirector.Definition d=defs.get(index++);try{test(d);}catch(Throwable e){JsonObject error=new JsonObject();error.addProperty("id",d.id);error.addProperty("passed",false);error.addProperty("error",e.toString());results.add(error);e.printStackTrace();}wait=active==null?20:200;return;}
  if(!Boolean.getBoolean("hbv.arenas.registryOnly")){
   try{if(!controllerStarted){controllerClass=Class.forName("village.vale.arenas.ControllerNativeChecks");controllerClass.getDeclaredMethod("begin",MinecraftServer.class,List.class,EntityPlayerMP.class).invoke(null,server,defs,player);controllerStarted=true;}boolean done=(Boolean)controllerClass.getDeclaredMethod("tick").invoke(null);if(!done){wait=1;return;}report.add("native_controller_cases",(JsonElement)controllerClass.getDeclaredMethod("result").invoke(null));player=(EntityPlayerMP)controllerClass.getDeclaredMethod("currentPlayer").invoke(null);}
   catch(ClassNotFoundException missing){report.addProperty("native_controller_cases","NOT_RUN");}
   catch(Throwable failure){JsonObject result=new JsonObject();result.addProperty("passed",false);result.addProperty("error",failure.toString());report.add("native_controller_cases",result);failure.printStackTrace();}
  }
  if(!Boolean.getBoolean("hbv.arenas.registryOnly")){
   try{if(!combatStarted){combatClass=Class.forName("village.vale.arenas.CombatNativeChecks");combatClass.getDeclaredMethod("begin",MinecraftServer.class,List.class,EntityPlayerMP.class).invoke(null,server,defs,player);combatStarted=true;}boolean complete=(Boolean)combatClass.getDeclaredMethod("tick").invoke(null);if(!complete){wait=1;return;}report.add("native_combat_cases",(JsonElement)combatClass.getDeclaredMethod("result").invoke(null));}
   catch(ClassNotFoundException absent){report.addProperty("native_combat_cases","NOT_RUN");}
   catch(Throwable failure){JsonObject failed=new JsonObject();failed.addProperty("passed",false);failed.addProperty("error",failure.toString());report.add("native_combat_cases",failed);failure.printStackTrace();}
  }
  enabled=false;report.addProperty("actual_private_network_manager_ticks",networkTicks);report.add("actual_native_player_end_ticks",ArenaDirector.JSON.toJsonTree(playerTicks));report.addProperty("network_scope","Guarded synthetic NetworkManager.processReceivedPackets plus real keepalive/teleport packet acknowledgements; no real client endpoint");try{if(player!=null)server.getPlayerList().playerLoggedOut(player);report.addProperty("duration_ms",(System.nanoTime()-started)/1000000);boolean passed=Boolean.getBoolean("hbv.arenas.controllerOnly")||results.size()==5;for(JsonElement e:results)passed&=e.getAsJsonObject().get("passed").getAsBoolean();if(report.has("native_outbox_cases")&&report.get("native_outbox_cases").isJsonObject())passed&=report.getAsJsonObject("native_outbox_cases").get("passed").getAsBoolean();if(report.has("native_outbox_restart")&&report.get("native_outbox_restart").isJsonObject())passed&=report.getAsJsonObject("native_outbox_restart").get("passed").getAsBoolean();if(report.has("native_core_reward_cases"))passed&=report.getAsJsonObject("native_core_reward_cases").get("passed").getAsBoolean();if(report.has("native_controller_cases")&&report.get("native_controller_cases").isJsonObject())passed&=report.getAsJsonObject("native_controller_cases").get("passed").getAsBoolean();if(report.has("native_combat_cases")&&report.get("native_combat_cases").isJsonObject())passed&=report.getAsJsonObject("native_combat_cases").get("passed").getAsBoolean();if(report.has("native_large_state_restart"))passed&=report.getAsJsonObject("native_large_state_restart").get("passed").getAsBoolean();if(report.has("actual_native_keepNinjaXp"))passed&=report.get("actual_native_keepNinjaXp").getAsBoolean();report.addProperty("passed",passed);report.addProperty("official_synthetic_login",player!=null);report.addProperty("save_restart","Python harness verifies second boot separately");try(Writer out=Files.newBufferedWriter(cwd.resolve("PRIVATE-ARENA-NATIVE-RESULT.json"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){ArenaDirector.JSON.toJson(report,out);}System.out.println("HBV_ARENA_NATIVE_RESULT passed="+passed);}catch(Throwable e){e.printStackTrace();}finally{server.initiateShutdown();}
 }
 static void test(ArenaDirector.Definition d)throws Exception{
  WorldServer w=server.getWorld(0);ensurePlayer(w);int spawnY=Boolean.getBoolean("hbv.arenas.registryOnly")?4:d.boss_anchor[1];player.setGameType(GameType.CREATIVE);player.setPositionAndUpdate(d.boss_anchor[0]+30.5,spawnY+4,d.boss_anchor[2]+.5);w.getPlayerChunkMap().updateMovingPlayer(player);JsonObject row=new JsonObject();row.addProperty("id",d.id);row.addProperty("template_sha256",d.template_sha256);JsonArray failures=new JsonArray(),anchors=new JsonArray();row.add("failures",failures);row.add("anchors",anchors);
  JsonArray palette=new JsonArray();row.add("native_palette_join",palette);if(d.palette!=null)for(Map.Entry<String,ArenaDirector.Palette> mapping:d.palette.entrySet()){int id=Integer.parseInt(mapping.getKey());Block block=Block.getBlockById(id);JsonObject p=new JsonObject();p.addProperty("id",id);p.addProperty("expected",mapping.getValue().name);p.addProperty("actual",String.valueOf(block.getRegistryName()));boolean match=mapping.getValue().name.equals(String.valueOf(block.getRegistryName()));p.addProperty("name_matches",match);if(!match)failures.add("Palette mismatch: "+id);JsonArray metas=new JsonArray();for(int meta:mapping.getValue().metadata){JsonObject state=new JsonObject();state.addProperty("meta",meta);int actual=block.getMetaFromState(block.getStateFromMeta(meta));state.addProperty("actual_roundtrip",actual);metas.add(state);if(actual!=meta)failures.add("Palette metadata normalization: "+id+":"+meta);}p.add("states",metas);palette.add(p);}
  if(!Boolean.getBoolean("hbv.arenas.registryOnly"))for(String name:new String[]{"entry","boss","reward","exit"}){int[] p=d.point(name);BlockPos b=new BlockPos(p[0],p[1],p[2]);prewarm(w,b);seedLights(w,d,b);w.checkLight(b.down());w.checkLight(b);boolean safe=ArenaDirector.safe(w,p);JsonObject a=new JsonObject();a.addProperty("name",name);a.addProperty("safe_native_human_aabb",safe);a.addProperty("block_light",w.getLightFor(EnumSkyBlock.BLOCK,b));a.addProperty("sky_light",w.getLightFor(EnumSkyBlock.SKY,b));a.addProperty("floor_registry",String.valueOf(w.getBlockState(b.down()).getBlock().getRegistryName()));a.addProperty("floor_meta",w.getBlockState(b.down()).getBlock().getMetaFromState(w.getBlockState(b.down())));anchors.add(a);if(!safe)failures.add("Unsafe anchor: "+name);if(w.getLightFor(EnumSkyBlock.BLOCK,b)<8)failures.add("Block light below8: "+name);}
  if(!Boolean.getBoolean("hbv.arenas.registryOnly")){
   if(d.services!=null)for(int[] point:d.services)prewarm(w,new BlockPos(point[0],point[1],point[2]));
   JsonObject services=ServicesNativeChecks.run(player,d);row.add("native_services",services);if(!services.get("passed").getAsBoolean())failures.add("Functional service actor cases failed");
   row.add("native_chests",storages(w,d,failures));
   player.setPositionAndUpdate(d.boss_anchor[0]+30.5,spawnY+4,d.boss_anchor[2]+.5);w.getPlayerChunkMap().updateMovingPlayer(player);
  }
  EntityEntry entry=ForgeRegistries.ENTITIES.getValue(new ResourceLocation(d.boss));JsonObject nativeBoss=new JsonObject();nativeBoss.addProperty("registry",d.boss);row.add("native_boss",nativeBoss);
  if(entry==null)failures.add("Missing exact native boss registry");else{
   Entity e=entry.newInstance(w);nativeBoss.addProperty("class",e.getClass().getName());nativeBoss.addProperty("class_sha256",ArenaTerminals.classHash(e));nativeBoss.addProperty("living",e instanceof EntityLivingBase);nativeBoss.addProperty("width",e.width);nativeBoss.addProperty("height",e.height);nativeBoss.addProperty("source",String.valueOf(e.getClass().getProtectionDomain().getCodeSource()));nativeBoss.addProperty("spawn_requirement","Entry.newInstance plus actual world spawn below");JsonArray methods=new JsonArray();for(java.lang.reflect.Method method:e.getClass().getMethods())if(method.getDeclaringClass()==e.getClass())methods.add(method.toGenericString());nativeBoss.add("declared_public_methods",methods);
   e.setPosition(d.boss_anchor[0]+.5,spawnY,d.boss_anchor[2]+.5);prewarm(w,e.getPosition());nativeBoss.addProperty("probe_spawn_y",spawnY);nativeBoss.addProperty("spawn_chunk_loaded",w.isBlockLoaded(e.getPosition()));nativeBoss.addProperty("before_spawn_dead",e.isDead);e.getEntityData().setString("HbvArenaNativeProbe",d.id);active=e;activeBoss=nativeBoss;activeDef=d;activeRow=row;routeIndex=0;row.add("native_route_samples",new JsonArray());activeStartTicks=e.ticksExisted;activeServerTicks=0;if(e instanceof EntityLiving){((EntityLiving)e).onInitialSpawn(w.getDifficultyForLocation(e.getPosition()),null);((EntityLiving)e).enablePersistence();}boolean spawned=w.spawnEntity(e);nativeBoss.addProperty("native_spawn_accepted",spawned);nativeBoss.addProperty("join_event_observed",joinEvent!=null);nativeBoss.addProperty("join_event_final_cancelled",joinEvent!=null&&joinEvent.isCanceled());if(!spawned)failures.add("Native spawn rejected");
   NBTTagCompound n=new NBTTagCompound();boolean serializable=e.writeToNBTOptional(n);nativeBoss.addProperty("saved_id",n.getString("id"));nativeBoss.addProperty("native_nbt_serializable",serializable);boolean bodyClear=w.getCollisionBoxes(e,e.getEntityBoundingBox()).isEmpty();nativeBoss.addProperty("body_aabb_clear",bodyClear);if(!bodyClear)failures.add("Native boss body collides at spawn");nativeBoss.addProperty("drops_xp_revival_and_renderer_accepted",false);if(spawned&&e instanceof EntityLivingBase){nativeBoss.addProperty("administrative_lethal_damage_accepted",e.attackEntityFrom(net.minecraft.util.DamageSource.OUT_OF_WORLD,Float.MAX_VALUE));nativeBoss.addProperty("immediate_health",((EntityLivingBase)e).getHealth());}
  }
  row.addProperty("registered_body_is_eligible_preview",ArenaDirector.eligible(player,true));
  ArenaDirector.Store s=ArenaDirector.store();NBTTagCompound before=s.writeToNBT(new NBTTagCompound());ArenaDirector.Store round=new ArenaDirector.Store();round.readFromNBT(before);row.addProperty("saved_state_roundtrip",before.equals(round.writeToNBT(new NBTTagCompound())));
  NBTTagCompound future=new NBTTagCompound();future.setString("Payload","{\"schema\":99,\"opaque\":{\"retain\":true}}");future.setString("UnknownRoot","preserve");ArenaDirector.Store unknown=new ArenaDirector.Store();unknown.readFromNBT(future);row.addProperty("future_schema_read_only",unknown.readOnly);row.addProperty("future_schema_byte_logical_preserved",future.equals(unknown.writeToNBT(new NBTTagCompound())));if(!unknown.readOnly||!future.equals(unknown.writeToNBT(new NBTTagCompound())))failures.add("Future schema preservation failed");
  JsonObject temporary=new JsonObject();temporary.add("cells",new JsonArray());BlockPos cell=new BlockPos(d.entry[0]+4,d.entry[1]-1,d.entry[2]);w.getChunk(cell);int initial=Block.getStateId(w.getBlockState(cell));ArenaDirector.journal(w,temporary,cell,net.minecraft.init.Blocks.GOLD_BLOCK.getDefaultState());ArenaDirector.applyJournal(temporary);boolean restored=ArenaDirector.restore(d,temporary)&&Block.getStateId(w.getBlockState(cell))==initial;row.addProperty("actual_owned_cell_journal_restore",restored);if(!restored)failures.add("Journal restoration failed");
  row.addProperty("native_phase_combat_and_restart_each_phase","NOT_RUN");row.addProperty("earned_terminal_and_reward_outbox","NOT_RUN_INTEGRATION_REQUIRED");row.addProperty("passed",failures.size()==0);results.add(row);
 }
 static void ensurePlayer(WorldServer w)throws Exception{if(player!=null)return;player=new EntityPlayerMP(server,w,new GameProfile(UUID.nameUUIDFromBytes("HBV:ArenaProbe:v1".getBytes(StandardCharsets.UTF_8)),"HbvArenaProbe"),new PlayerInteractionManager(w));player.connection=new Quiet(server,player);server.getPlayerList().initializeConnectionToPlayer(player.connection.netManager,player,player.connection);if(server.getPlayerList().getPlayerByUUID(player.getUniqueID())!=player)throw new AssertionError("Official login failed");try{Class<?> checks=Class.forName("village.vale.arenas.OutboxNativeChecks");Object tests=checks.getDeclaredMethod("run",EntityPlayerMP.class).invoke(null,player);report.add("native_outbox_cases",(JsonElement)tests);Object core=Class.forName("village.vale.arenas.CoreRewardNativeChecks").getDeclaredMethod("run",EntityPlayerMP.class).invoke(null,player);report.add("native_core_reward_cases",(JsonElement)core);Object restart=checks.getDeclaredMethod("runRestartCase",EntityPlayerMP.class).invoke(null,player);report.add("native_outbox_restart",(JsonElement)restart);report.add("native_large_state_restart",LargeStateNativeChecks.run(player,defs.get(0)));try{boolean keep=(Boolean)Class.forName("net.narutomod.PlayerTracker").getMethod("keepNinjaXp",World.class).invoke(null,w);report.addProperty("actual_native_keepNinjaXp",keep);}catch(ReflectiveOperationException missing){report.addProperty("actual_native_keepNinjaXp",false);}}catch(ClassNotFoundException absent){report.addProperty("native_outbox_cases","NOT_RUN");}}
 static void prewarm(WorldServer w,BlockPos center){for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)w.getChunk((center.getX()>>4)+x,(center.getZ()>>4)+z);}


 static JsonArray storages(WorldServer w,ArenaDirector.Definition d,JsonArray failures){JsonArray result=new JsonArray();if(d.containers==null)return result;for(ArenaDirector.Storage storage:d.containers){BlockPos pos=new BlockPos(storage.at[0],storage.at[1],storage.at[2]);prewarm(w,pos);JsonObject row=new JsonObject();row.addProperty("room",storage.name);net.minecraft.tileentity.TileEntity tile=w.getTileEntity(pos);boolean typed=tile instanceof net.minecraft.tileentity.TileEntityChest;row.addProperty("native_chest_tile",typed);boolean opened=false;if(typed){player.setPositionAndUpdate(storage.front[0]+.5,storage.front[1],storage.front[2]+.5);player.displayGUIChest((net.minecraft.tileentity.TileEntityChest)tile);opened=player.openContainer instanceof net.minecraft.inventory.ContainerChest&&((net.minecraft.inventory.ContainerChest)player.openContainer).getLowerChestInventory()==tile;player.closeScreen();NBTTagCompound n=tile.writeToNBT(new NBTTagCompound());row.addProperty("native_saved_tile_id",n.getString("id"));row.addProperty("native_metadata",w.getBlockState(pos).getBlock().getMetaFromState(w.getBlockState(pos)));row.addProperty("native_empty",((net.minecraft.tileentity.TileEntityChest)tile).isEmpty());}row.addProperty("actual_container_opened",opened);if(!typed||!opened)failures.add("Native functional chest failed: "+storage.name);result.add(row);}return result;}
 static void seedLights(WorldServer w,ArenaDirector.Definition d,BlockPos center){if(d.lights==null)return;for(int[] light:d.lights){BlockPos pos=new BlockPos(light[0],light[1],light[2]);if(Math.abs(pos.getX()-center.getX())+Math.abs(pos.getY()-center.getY())+Math.abs(pos.getZ()-center.getZ())<=20&&w.isBlockLoaded(pos))w.checkLightFor(EnumSkyBlock.BLOCK,pos);}}
 static void routeBatch(){
  if(activeDef==null||activeDef.samples==null)return;WorldServer w=server.getWorld(0);JsonArray rows=activeRow.getAsJsonArray("native_route_samples");
  for(int n=0;n<4&&routeIndex<activeDef.samples.length;n++){ArenaDirector.Sample sample=activeDef.samples[routeIndex++];BlockPos point=new BlockPos(sample.at[0],sample.at[1],sample.at[2]);prewarm(w,point);seedLights(w,activeDef,point);boolean safe=ArenaDirector.safe(w,sample.at);int light=w.getLightFor(EnumSkyBlock.BLOCK,point);JsonObject row=new JsonObject();row.addProperty("route",sample.name);JsonArray at=new JsonArray();for(int value:sample.at)at.add(value);row.add("at",at);row.addProperty("native_human_collision_and_support",safe);row.addProperty("native_block_light",light);rows.add(row);if(!safe||light<8){activeRow.getAsJsonArray("failures").add("Native route "+sample.name+" sample"+(routeIndex-1)+" collision="+safe+" blocklight="+light);activeRow.addProperty("passed",false);}
   for(net.minecraft.world.chunk.Chunk chunk:new ArrayList<>(w.getChunkProvider().getLoadedChunks()))if(Math.abs(chunk.x-(active.getPosition().getX()>>4))>2||Math.abs(chunk.z-(active.getPosition().getZ()>>4))>2)w.getChunkProvider().queueUnload(chunk);
  }
 }
 static final class Quiet extends NetHandlerPlayServer {
  Quiet(MinecraftServer s,EntityPlayerMP p){super(s,network(),p);}
  static NetworkManager network(){NetworkManager n=new NetworkManager(EnumPacketDirection.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(n){protected java.net.SocketAddress remoteAddress0(){return new java.net.InetSocketAddress("127.0.0.1",0);}};n.setConnectionState(EnumConnectionState.PLAY);return n;}
  public void sendPacket(Packet<?> p){if(p instanceof net.minecraft.network.play.server.SPacketKeepAlive)processKeepAlive(new net.minecraft.network.play.client.CPacketKeepAlive(((net.minecraft.network.play.server.SPacketKeepAlive)p).getId()));else if(p instanceof net.minecraft.network.play.server.SPacketPlayerPosLook)processConfirmTeleport(new net.minecraft.network.play.client.CPacketConfirmTeleport(((net.minecraft.network.play.server.SPacketPlayerPosLook)p).getTeleportId()));}
 }
}
